// ---------------------------------------------------------------------------
// CSV-Dateien in einzelne Zeilen zerlegen.
// Modus: "Run Once for All Items" - herein kommt ein Eintrag je Datei,
// heraus geht ein Eintrag je Datenzeile.
//
// Warum nicht der Knoten "Extract from File": der entscheidet das Trennzeichen
// selbst. Bei deutschen Dateien ist das Semikolon ueblich, bei englischen das
// Komma - und wer hier falsch raet, bekommt eine einzige Spalte und merkt es
// erst drei Schritte spaeter. Das Trennzeichen wird deshalb an der Kopfzeile
// festgestellt und bei Gleichstand abgelehnt.
// ---------------------------------------------------------------------------

const TRENNZEICHEN = [';', ',', '\t', '|'];

// Zerlegt nach RFC 4180: Anfuehrungszeichen schuetzen Trennzeichen und
// Zeilenumbrueche, ein doppeltes Anfuehrungszeichen steht fuer sich selbst.
function zerlegen(text, trenner) {
  const zeilen = [];
  let feld = '', zeile = [], inAnfuehrung = false;

  for (let i = 0; i < text.length; i++) {
    const z = text[i];
    if (inAnfuehrung) {
      if (z === '"') {
        if (text[i + 1] === '"') { feld += '"'; i++; } else { inAnfuehrung = false; }
      } else { feld += z; }
      continue;
    }
    if (z === '"' && feld === '') { inAnfuehrung = true; continue; }
    if (z === trenner) { zeile.push(feld); feld = ''; continue; }
    if (z === '\r') continue;
    if (z === '\n') { zeile.push(feld); zeilen.push(zeile); zeile = []; feld = ''; continue; }
    feld += z;
  }
  if (feld !== '' || zeile.length) { zeile.push(feld); zeilen.push(zeile); }
  return zeilen;
}

function trennerFinden(kopfzeile) {
  const treffer = TRENNZEICHEN
    .map(t => ({ t, anzahl: (kopfzeile.match(new RegExp(`\\${t}`, 'g')) || []).length }))
    .filter(x => x.anzahl > 0)
    .sort((a, b) => b.anzahl - a.anzahl);

  if (!treffer.length) {
    throw new Error('Die Kopfzeile enthaelt kein bekanntes Trennzeichen '
                  + `(gesucht: ${TRENNZEICHEN.map(t => t === '\t' ? 'Tab' : t).join(' ')})`);
  }
  if (treffer.length > 1 && treffer[0].anzahl === treffer[1].anzahl) {
    throw new Error(`Trennzeichen nicht eindeutig: "${treffer[0].t}" und `
                  + `"${treffer[1].t}" kommen gleich oft vor`);
  }
  return treffer[0].t;
}

const ausgabe = [];
const eintraege = $input.all();

for (let i = 0; i < eintraege.length; i++) {
  const datei = eintraege[i].binary?.data?.fileName || `datei-${i + 1}.csv`;
  const puffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  // Byte Order Mark entfernen - Excel schreibt ihn beim Speichern als CSV UTF-8.
  const text = puffer.toString('utf8').replace(/^﻿/, '');

  if (!text.trim()) {
    ausgabe.push({ json: { __datei: datei, __zeile: 0, __fehler: 'Datei ist leer' } });
    continue;
  }

  let trenner;
  try {
    trenner = trennerFinden(text.split(/\r?\n/, 1)[0]);
  } catch (e) {
    ausgabe.push({ json: { __datei: datei, __zeile: 1, __fehler: e.message } });
    continue;
  }

  const zeilen = zerlegen(text, trenner);
  const kopf = zeilen[0].map(s => s.trim().toLowerCase().replace(/^﻿/, ''));

  for (let z = 1; z < zeilen.length; z++) {
    const felder = zeilen[z];
    if (felder.every(f => f.trim() === '')) continue;   // Leerzeile ueberspringen

    const datensatz = { __datei: datei, __zeile: z + 1 };
    if (felder.length !== kopf.length) {
      datensatz.__fehler = `${felder.length} Felder, die Kopfzeile hat ${kopf.length}`;
    }
    kopf.forEach((spalte, s) => { datensatz[spalte] = (felder[s] ?? '').trim(); });
    ausgabe.push({ json: datensatz });
  }
}

return ausgabe;

// ---------------------------------------------------------------------------
// CSV-Zeilen pruefen und zu Rechnungen buendeln.
// Modus: "Run Once for All Items" - herein kommt ein Eintrag je CSV-Zeile,
// heraus geht ein Eintrag je Rechnung. Mehr Eintraege ausgeben als hereinkamen
// kann ein Code-Knoten nur in diesem Modus, weniger ebenso.
//
// Leitsatz wie im Python-Teil: niemals raten. Was nicht eindeutig ist, wird
// zum Problemfall und nicht zu einer Schaetzung. Der IF-Knoten dahinter
// trennt anhand von "ok" die beiden Wege.
// ---------------------------------------------------------------------------

// --- Einstellungen, die ein Kunde anpassen wuerde --------------------------
const PFLICHTSPALTEN = [
  'rechnungsnummer', 'rechnungsdatum', 'kundennummer', 'kunde',
  'strasse', 'plz_ort', 'position', 'beschreibung',
  'menge', 'einheit', 'einzelpreis', 'mwst_satz',
];
const ERLAUBTE_MWST = [0, 7, 19];
// Zahlen kommen in deutscher Schreibweise: das Komma trennt die Nachkommastellen.
const DEZIMALTRENNER = ',';
// ---------------------------------------------------------------------------

const zeilen = $input.all();
const problemfaelle = [];
const rechnungen = new Map();
// Je Rechnungsnummer: wie viele Zeilen insgesamt, wie viele davon fehlerhaft.
// Ist auch nur eine Zeile kaputt, entsteht fuer diese Nummer kein PDF -
// sonst fehlte auf der Rechnung stillschweigend eine Position.
const zeilenJeRechnung = new Map();
const kaputtJeRechnung = new Map();

function meldung(datei, zeilennr, nummer, grund) {
  problemfaelle.push({
    json: { ok: false, datei, zeile: zeilennr, rechnungsnummer: nummer, problem: grund },
  });
  if (nummer && zeilennr !== '') {
    kaputtJeRechnung.set(nummer, (kaputtJeRechnung.get(nummer) || 0) + 1);
  }
}

// Betrag nach den Regeln des PDF-Extractors: der Trenner muss benannt sein,
// und was auf beide Weisen lesbar waere, wird abgelehnt statt geraten.
function betrag(roh) {
  const s = String(roh == null ? '' : roh).trim().replace(/[\s ]/g, '');
  if (s === '') throw new Error('Zahl fehlt');
  if (!/^-?[\d.,]+$/.test(s)) throw new Error(`"${roh}" ist keine Zahl`);

  const komma = s.lastIndexOf(',');
  const punkt = s.lastIndexOf('.');
  const punkte = (s.match(/\./g) || []).length;

  if ((s.match(/,/g) || []).length > 1) {
    throw new Error(`"${roh}" enthaelt mehr als ein Komma`);
  }
  if (komma !== -1 && punkt > komma) {
    throw new Error(`"${roh}" mischt Punkt und Komma in ungewohnter Reihenfolge`);
  }
  if (komma === -1 && punkte === 1) {
    // Kein Komma, genau ein Punkt: "1.234" heisst auf Deutsch 1234,
    // auf Englisch 1,234. Beides ist vertretbar, also wird nicht geraten.
    if (s.length - punkt - 1 === 3) {
      throw new Error(`"${roh}" ist zweideutig - bitte den Dezimaltrenner `
                    + `"${DEZIMALTRENNER}" benutzen`);
    }
    throw new Error(`"${roh}" benutzt den Punkt als Dezimaltrenner, `
                  + `erwartet wird "${DEZIMALTRENNER}"`);
  }

  // Formpruefung vor dem Rechnen: "1.2.00" wuerde sonst still zu 1200.
  const vorkomma = s.replace(/^-/, '').split(',')[0];
  if (vorkomma.includes('.')) {
    const gruppen = vorkomma.split('.');
    if (gruppen.slice(1).some(g => g.length !== 3)
        || gruppen[0].length < 1 || gruppen[0].length > 3) {
      throw new Error(`"${roh}" hat keine saubere Tausendergliederung`);
    }
  }

  const zahl = Number(s.replace(/\./g, '').replace(',', '.'));
  if (!Number.isFinite(zahl)) throw new Error(`"${roh}" ist keine Zahl`);
  return zahl;
}

function datum(roh) {
  const s = String(roh == null ? '' : roh).trim();
  const m = s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  if (!m) throw new Error(`"${roh}" ist kein Datum im Format TT.MM.JJJJ`);
  const t = Number(m[1]), mo = Number(m[2]), j = Number(m[3]);
  const d = new Date(Date.UTC(j, mo - 1, t));
  if (d.getUTCFullYear() !== j || d.getUTCMonth() !== mo - 1 || d.getUTCDate() !== t) {
    throw new Error(`"${roh}" gibt es im Kalender nicht`);
  }
  return s;
}

// --- Durchlauf -------------------------------------------------------------
for (const eintrag of zeilen) {
  const z = eintrag.json;
  const datei = z.__datei || 'unbekannt.csv';
  const zeilennr = z.__zeile ?? '';
  const nummer = String(z.rechnungsnummer ?? '').trim();
  if (nummer) zeilenJeRechnung.set(nummer, (zeilenJeRechnung.get(nummer) || 0) + 1);

  // Was schon beim Einlesen aufgefallen ist, wird nicht noch einmal geprueft.
  if (z.__fehler) {
    meldung(datei, zeilennr, nummer, z.__fehler);
    continue;
  }

  const fehlend = PFLICHTSPALTEN.filter(s => !(s in z));
  if (fehlend.length) {
    meldung(datei, zeilennr, nummer, `Spalten fehlen: ${fehlend.join(', ')}`);
    continue;
  }

  if (!nummer) {
    meldung(datei, zeilennr, '', 'Rechnungsnummer ist leer');
    continue;
  }

  let posten;
  try {
    const satz = betrag(z.mwst_satz);
    if (!ERLAUBTE_MWST.includes(satz)) {
      throw new Error(`MwSt-Satz ${satz} ist nicht vorgesehen `
                    + `(erlaubt: ${ERLAUBTE_MWST.join(', ')})`);
    }
    posten = {
      position: Number(String(z.position).trim()),
      beschreibung: String(z.beschreibung ?? '').trim(),
      menge: betrag(z.menge),
      einheit: String(z.einheit ?? '').trim(),
      einzelpreis: betrag(z.einzelpreis),
      mwst_satz: satz,
      zeile: zeilennr,
    };
    if (!Number.isInteger(posten.position) || posten.position < 1) {
      throw new Error(`Position "${z.position}" ist keine laufende Nummer`);
    }
    if (!posten.beschreibung) throw new Error('Beschreibung ist leer');
  } catch (e) {
    meldung(datei, zeilennr, nummer, e.message);
    continue;
  }

  const kopf = {
    rechnungsnummer: nummer,
    kundennummer: String(z.kundennummer ?? '').trim(),
    kunde: String(z.kunde ?? '').trim(),
    strasse: String(z.strasse ?? '').trim(),
    plz_ort: String(z.plz_ort ?? '').trim(),
  };
  try {
    kopf.rechnungsdatum = datum(z.rechnungsdatum);
  } catch (e) {
    meldung(datei, zeilennr, nummer, e.message);
    continue;
  }

  if (!rechnungen.has(nummer)) {
    rechnungen.set(nummer, { kopf, datei, posten: [], fehler: [] });
  }
  const r = rechnungen.get(nummer);

  // Die Kopfdaten muessen ueber alle Zeilen einer Rechnung zusammenpassen.
  // Zwei verschiedene Kunden unter einer Nummer sind ein Datenfehler, kein Fall
  // fuer "der erste gewinnt".
  for (const feld of Object.keys(kopf)) {
    if (r.kopf[feld] !== kopf[feld]) {
      r.fehler.push(`Zeile ${zeilennr}: ${feld} lautet "${kopf[feld]}", `
                  + `weiter oben in derselben Rechnung "${r.kopf[feld]}"`);
    }
  }
  if (r.posten.some(p => p.position === posten.position)) {
    r.fehler.push(`Zeile ${zeilennr}: Position ${posten.position} kommt doppelt vor`);
  }
  r.posten.push(posten);
}

// --- Ergebnis --------------------------------------------------------------
const fertig = [];
for (const [nummer, r] of rechnungen) {
  if (r.fehler.length) {
    // Lieber gar keine Rechnung als eine halbe: die Widersprueche wandern in
    // den Problembericht, es entsteht kein PDF.
    for (const f of r.fehler) meldung(r.datei, '', nummer, f);
    continue;
  }
  const kaputt = kaputtJeRechnung.get(nummer) || 0;
  if (kaputt) {
    meldung(r.datei, '', nummer,
      `Keine Rechnung erstellt: ${kaputt} von ${zeilenJeRechnung.get(nummer)} Zeilen `
      + `fehlerhaft, das PDF waere unvollstaendig`);
    continue;
  }
  r.posten.sort((a, b) => a.position - b.position);

  let netto = 0;
  const steuer = new Map();
  for (const p of r.posten) {
    p.betrag = Math.round(p.menge * p.einzelpreis * 100) / 100;
    netto += p.betrag;
    steuer.set(p.mwst_satz, (steuer.get(p.mwst_satz) || 0) + p.betrag);
  }
  netto = Math.round(netto * 100) / 100;

  const steuerzeilen = [...steuer.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([satz, basis]) => {
      const gerundet = Math.round(basis * 100) / 100;
      return { satz, basis: gerundet, betrag: Math.round(gerundet * satz) / 100 };
    });
  const steuersumme = Math.round(steuerzeilen.reduce((a, s) => a + s.betrag, 0) * 100) / 100;

  fertig.push({
    json: {
      ok: true,
      ...r.kopf,
      datei: r.datei,
      posten: r.posten,
      netto,
      steuerzeilen,
      steuersumme,
      brutto: Math.round((netto + steuersumme) * 100) / 100,
    },
  });
}

fertig.sort((a, b) =>
  a.json.rechnungsnummer.localeCompare(b.json.rechnungsnummer, 'de', { numeric: true }));

return [...fertig, ...problemfaelle];

// ---------------------------------------------------------------------------
// Aus jeder geprueften Rechnung ein PDF bauen.
// Modus: "Run Once for All Items" - je Eintrag ein PDF im Binaerfeld "data".
//
// Warum von Hand und nicht mit pdfkit: im offiziellen n8n-Image laesst sich
// kein npm-Paket nachinstallieren, und NODE_FUNCTION_ALLOW_EXTERNAL hilft nur
// bei Paketen, die schon im Container liegen. Ein PDF mit den 14 eingebauten
// Schriften ist aber ein ueberschaubares Format: Objekte, eine Positionsliste
// (xref) mit Byte-Abstaenden, ein Anhang. Genau das steht hier unten.
// ---------------------------------------------------------------------------

// --- Absender: die einzige Stelle, die ein Kunde anpassen muss -------------
const ABSENDER = {
  zeilen: ['Musterbetrieb GmbH', 'Beispielweg 1', '83454 Anger'],
  fuss: [
    'Musterbetrieb GmbH · Beispielweg 1 · 83454 Anger · USt-IdNr. DE000000000',
    'Bankverbindung: Musterbank · IBAN DE00 0000 0000 0000 0000 00 · BIC MUSTDEFFXXX',
  ],
  zahlungsziel: 'Zahlbar ohne Abzug innerhalb von 14 Tagen nach Rechnungserhalt.',
};
// ---------------------------------------------------------------------------

// ===========================================================================
// Teil 1: Schrift
// ===========================================================================

// Zeichenbreiten der eingebauten Helvetica in 1/1000 der Schriftgroesse.
// Ohne sie laesst sich nichts rechtsbuendig setzen - und krumme Betragsspalten
// sind das Erste, was auf einer Rechnung auffaellt.
const BREITEN_NORMAL = {};
const BREITEN_FETT = {};
(function breitenAufbauen() {
  const normal =
    '278 278 355 556 556 889 667 191 333 333 389 584 278 333 278 278 ' +   // 32-47
    '556 556 556 556 556 556 556 556 556 556 278 278 584 584 584 556 ' +   // 48-63
    '1015 667 667 722 722 667 611 778 722 278 500 667 556 833 722 778 ' +  // 64-79
    '667 778 722 667 611 722 667 944 667 667 611 278 278 278 469 556 ' +   // 80-95
    '333 556 556 500 556 556 278 556 556 222 222 500 222 833 556 556 ' +   // 96-111
    '556 556 333 500 278 556 500 722 500 500 500 334 260 334 584';         // 112-126
  const fett =
    '278 333 474 556 556 889 722 238 333 333 389 584 278 333 278 278 ' +
    '556 556 556 556 556 556 556 556 556 556 333 333 584 584 584 611 ' +
    '975 722 722 722 722 667 611 778 722 278 556 722 611 833 722 778 ' +
    '667 778 722 667 611 722 667 944 667 667 611 333 278 333 584 556 ' +
    '333 556 611 556 611 556 333 611 611 278 278 556 278 889 611 611 ' +
    '611 611 389 556 333 611 556 778 556 556 500 389 280 389 584';
  normal.trim().split(/\s+/).forEach((b, i) => { BREITEN_NORMAL[32 + i] = Number(b); });
  fett.trim().split(/\s+/).forEach((b, i) => { BREITEN_FETT[32 + i] = Number(b); });

  // Umlaute und Zeichen aus dem oberen WinAnsi-Bereich. In Helvetica ist ein
  // Buchstabe mit Akzent genauso breit wie der Buchstabe darunter.
  const wie = { 196: 65, 214: 79, 220: 85, 228: 97, 246: 111, 252: 117,
                233: 101, 232: 101, 224: 97 };
  for (const [zeichen, vorbild] of Object.entries(wie)) {
    BREITEN_NORMAL[zeichen] = BREITEN_NORMAL[vorbild];
    BREITEN_FETT[zeichen] = BREITEN_FETT[vorbild];
  }
  // Eigene Breiten laut Helvetica-AFM
  BREITEN_NORMAL[223] = 611; BREITEN_FETT[223] = 611;   // ß
  BREITEN_NORMAL[128] = 556; BREITEN_FETT[128] = 556;   // €
  BREITEN_NORMAL[167] = 556; BREITEN_FETT[167] = 556;   // §
  BREITEN_NORMAL[176] = 400; BREITEN_FETT[176] = 400;   // °
  BREITEN_NORMAL[183] = 278; BREITEN_FETT[183] = 278;   // ·
})();

// WinAnsiEncoding deckt Latin-1 ab und ein paar Sonderzeichen davor.
// Was nicht hineinpasst, wird ersetzt - und das steht spaeter im Protokoll,
// damit niemand ein stillschweigend verstuemmeltes PDF verschickt.
const ERSATZ = { '€': '\x80', '–': '-', '—': '-', '‘': "'",
                 '’': "'", '“': '"', '”': '"', '•': '\xB7' };
const verstuemmelt = new Set();

function nachWinAnsi(text) {
  let aus = '';
  for (const zeichen of String(text ?? '')) {
    if (ERSATZ[zeichen] !== undefined) { aus += ERSATZ[zeichen]; continue; }
    const nr = zeichen.codePointAt(0);
    if (nr >= 32 && nr <= 126) { aus += zeichen; continue; }
    if (nr >= 160 && nr <= 255) { aus += zeichen; continue; }
    if (zeichen === '\t') { aus += ' '; continue; }
    verstuemmelt.add(zeichen);
    aus += '?';
  }
  return aus;
}

function breite(text, groesse, fett) {
  const tabelle = fett ? BREITEN_FETT : BREITEN_NORMAL;
  let summe = 0;
  for (let i = 0; i < text.length; i++) {
    summe += tabelle[text.charCodeAt(i)] ?? 556;
  }
  return summe * groesse / 1000;
}

// Zu langen Text kuerzen statt ueber den Rand laufen zu lassen.
function kuerzen(text, maxBreite, groesse, fett) {
  if (breite(text, groesse, fett) <= maxBreite) return text;
  let kurz = text;
  while (kurz.length > 1 && breite(kurz + '...', groesse, fett) > maxBreite) {
    kurz = kurz.slice(0, -1);
  }
  return kurz + '...';
}

// ===========================================================================
// Teil 2: Seite und Inhaltsstrom
// ===========================================================================

const A4 = { breite: 595.28, hoehe: 841.89 };
const RAND = { links: 56.7, rechts: 56.7, oben: 56.7, unten: 70 };

function escapePdf(text) {
  return text.replace(/([\\()])/g, '\\$1');
}

class Seite {
  constructor() { this.teile = []; }
  text(x, y, inhalt, groesse, fett, farbe) {
    const t = escapePdf(nachWinAnsi(inhalt));
    const f = farbe || [0, 0, 0];
    this.teile.push(
      `BT ${f[0]} ${f[1]} ${f[2]} rg /${fett ? 'F2' : 'F1'} ${groesse} Tf ` +
      `1 0 0 1 ${x.toFixed(2)} ${y.toFixed(2)} Tm (${t}) Tj ET`);
  }
  textRechts(x, y, inhalt, groesse, fett, farbe) {
    const t = nachWinAnsi(inhalt);
    this.text(x - breite(t, groesse, fett), y, inhalt, groesse, fett, farbe);
  }
  linie(x1, y1, x2, y2, staerke, farbe) {
    const f = farbe || [0, 0, 0];
    this.teile.push(
      `${f[0]} ${f[1]} ${f[2]} RG ${staerke} w ` +
      `${x1.toFixed(2)} ${y1.toFixed(2)} m ${x2.toFixed(2)} ${y2.toFixed(2)} l S`);
  }
  flaeche(x, y, b, h, farbe) {
    this.teile.push(
      `${farbe[0]} ${farbe[1]} ${farbe[2]} rg ` +
      `${x.toFixed(2)} ${y.toFixed(2)} ${b.toFixed(2)} ${h.toFixed(2)} re f`);
  }
  get inhalt() { return this.teile.join('\n'); }
}

// Setzt die Objekte zusammen und rechnet die Byte-Abstaende fuer die xref aus.
// Ein falscher Abstand hier und der Reader meldet "damaged file" - deshalb
// wird strikt in latin1 gezaehlt, wo ein Zeichen genau ein Byte ist.
function pdfBauen(seiten) {
  const objekte = [];
  const nr = () => objekte.length + 1;

  const katalogNr = nr(); objekte.push(null);          // 1, wird nachgetragen
  const seitenbaumNr = nr(); objekte.push(null);       // 2
  const fontNormalNr = nr();
  objekte.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica '
             + '/Encoding /WinAnsiEncoding >>');
  const fontFettNr = nr();
  objekte.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold '
             + '/Encoding /WinAnsiEncoding >>');

  const seitenNummern = [];
  for (const seite of seiten) {
    const strom = seite.inhalt;
    const stromNr = nr();
    objekte.push(`<< /Length ${Buffer.byteLength(strom, 'latin1')} >>\n`
               + `stream\n${strom}\nendstream`);
    const seiteNr = nr();
    objekte.push(
      `<< /Type /Page /Parent ${seitenbaumNr} 0 R `
      + `/MediaBox [0 0 ${A4.breite} ${A4.hoehe}] `
      + `/Resources << /Font << /F1 ${fontNormalNr} 0 R /F2 ${fontFettNr} 0 R >> >> `
      + `/Contents ${stromNr} 0 R >>`);
    seitenNummern.push(seiteNr);
  }

  objekte[katalogNr - 1] = `<< /Type /Catalog /Pages ${seitenbaumNr} 0 R >>`;
  objekte[seitenbaumNr - 1] =
    `<< /Type /Pages /Kids [${seitenNummern.map(n => `${n} 0 R`).join(' ')}] `
    + `/Count ${seitenNummern.length} >>`;

  let text = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
  const abstaende = [];
  for (let i = 0; i < objekte.length; i++) {
    abstaende.push(Buffer.byteLength(text, 'latin1'));
    text += `${i + 1} 0 obj\n${objekte[i]}\nendobj\n`;
  }
  const xrefAbstand = Buffer.byteLength(text, 'latin1');
  text += `xref\n0 ${objekte.length + 1}\n0000000000 65535 f \n`;
  for (const a of abstaende) {
    text += `${String(a).padStart(10, '0')} 00000 n \n`;
  }
  text += `trailer\n<< /Size ${objekte.length + 1} /Root ${katalogNr} 0 R >>\n`
        + `startxref\n${xrefAbstand}\n%%EOF\n`;

  return Buffer.from(text, 'latin1');
}

// ===========================================================================
// Teil 3: Das Rechnungsformular
// ===========================================================================

const GRAU = [0.45, 0.45, 0.45];
const LINIE = [0.75, 0.75, 0.75];
const KOPFBALKEN = [0.93, 0.94, 0.96];

function euro(betrag) {
  const v = Math.abs(betrag).toFixed(2).replace('.', ',');
  const mit = v.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (betrag < 0 ? '-' : '') + mit;
}
function menge(wert) {
  return (Number.isInteger(wert) ? String(wert) : wert.toFixed(2)).replace('.', ',');
}

function rechnungBauen(r) {
  const seiten = [];
  const links = RAND.links;
  const rechts = A4.breite - RAND.rechts;

  // Spalten der Positionstabelle. Die Zahlen sind die rechte Kante der
  // jeweiligen Spalte; nur "pos" und "text" werden linksbuendig gesetzt.
  // Die Abstaende sind so gewaehlt, dass auch die fetten Ueberschriften
  // ("Einzelpreis", "Betrag EUR") nicht in die Nachbarspalte ragen.
  const spalten = {
    pos:    links,
    text:   links + 32,
    menge:  links + 290,
    einzel: links + 375,
    mwst:   links + 428,
    betrag: rechts,
  };
  // Rechte Kante der Beschriftungen im Summenblock.
  const summenBeschriftung = rechts - 70;

  let seite, y, seitenzahl = 0;

  function fussZeile(s) {
    s.linie(links, RAND.unten, rechts, RAND.unten, 0.5, LINIE);
    let fy = RAND.unten - 12;
    for (const zeile of ABSENDER.fuss) {
      s.text(links, fy, zeile, 7, false, GRAU);
      fy -= 9;
    }
  }

  function tabellenkopf() {
    seite.flaeche(links, y - 4, rechts - links, 16, KOPFBALKEN);
    seite.text(spalten.pos, y, 'Pos', 8, true);
    seite.text(spalten.text, y, 'Beschreibung', 8, true);
    seite.textRechts(spalten.menge, y, 'Menge', 8, true);
    seite.textRechts(spalten.einzel, y, 'Einzelpreis', 8, true);
    seite.textRechts(spalten.mwst, y, 'MwSt', 8, true);
    seite.textRechts(spalten.betrag, y, 'Betrag EUR', 8, true);
    y -= 18;
  }

  function neueSeite(mitBriefkopf) {
    seite = new Seite();
    seiten.push(seite);
    seitenzahl++;
    y = A4.hoehe - RAND.oben;

    if (mitBriefkopf) {
      // Absender rechts oben
      let ay = y;
      for (let i = 0; i < ABSENDER.zeilen.length; i++) {
        seite.textRechts(rechts, ay, ABSENDER.zeilen[i], i === 0 ? 11 : 9,
                         i === 0, i === 0 ? null : GRAU);
        ay -= i === 0 ? 15 : 11;
      }
      // Anschriftenfeld links, auf DIN-5008-Hoehe
      let ky = y - 45;
      seite.text(links, ky + 14, `${ABSENDER.zeilen[0]} · ${ABSENDER.zeilen[1]} · `
                               + `${ABSENDER.zeilen[2]}`, 6.5, false, GRAU);
      for (const zeile of [r.kunde, r.strasse, r.plz_ort]) {
        if (zeile) { seite.text(links, ky, zeile, 10.5, false); ky -= 13; }
      }

      y = ky - 42;
      seite.text(links, y, `Rechnung ${r.rechnungsnummer}`, 16, true);
      y -= 20;
      seite.text(links, y,
        `Rechnungsdatum ${r.rechnungsdatum}   ·   Kundennummer ${r.kundennummer}`,
        9, false, GRAU);
      y -= 26;
    } else {
      seite.text(links, y, `Rechnung ${r.rechnungsnummer} · Fortsetzung`, 10, true);
      y -= 24;
    }
    tabellenkopf();
  }

  neueSeite(true);

  // --- Positionen ----------------------------------------------------------
  for (const p of r.posten) {
    // Platz fuer diese Zeile und die Summenblocks im Blick behalten
    if (y < RAND.unten + 40) neueSeite(false);

    const beschreibung = kuerzen(p.beschreibung, spalten.menge - spalten.text - 45, 9, false);
    seite.text(spalten.pos, y, String(p.position), 9);
    seite.text(spalten.text, y, beschreibung, 9);
    seite.textRechts(spalten.menge, y,
      `${menge(p.menge)}${p.einheit ? ' ' + p.einheit : ''}`, 9);
    seite.textRechts(spalten.einzel, y, euro(p.einzelpreis), 9);
    seite.textRechts(spalten.mwst, y, `${p.mwst_satz} %`, 9);
    seite.textRechts(spalten.betrag, y, euro(p.betrag), 9);
    y -= 6;
    seite.linie(links, y, rechts, y, 0.4, LINIE);
    y -= 12;
  }

  // --- Summen --------------------------------------------------------------
  const summenHoehe = 26 + r.steuerzeilen.length * 13 + 30;
  if (y < RAND.unten + summenHoehe) neueSeite(false);

  y -= 6;
  seite.textRechts(summenBeschriftung, y, 'Nettobetrag', 9);
  seite.textRechts(spalten.betrag, y, euro(r.netto), 9);
  y -= 13;
  for (const s of r.steuerzeilen) {
    seite.textRechts(summenBeschriftung, y,
      `zzgl. ${s.satz} % MwSt auf ${euro(s.basis)}`, 9);
    seite.textRechts(spalten.betrag, y, euro(s.betrag), 9);
    y -= 13;
  }
  y -= 2;
  seite.linie(spalten.einzel - 60, y + 6, rechts, y + 6, 0.8, [0.2, 0.2, 0.2]);
  y -= 8;
  seite.textRechts(summenBeschriftung, y, 'Gesamtbetrag', 11, true);
  seite.textRechts(spalten.betrag, y, euro(r.brutto), 11, true);

  y -= 34;
  if (y < RAND.unten + 20) { neueSeite(false); y -= 10; }
  seite.text(links, y, ABSENDER.zahlungsziel, 9);

  // --- Fusszeilen und Seitenzahlen -----------------------------------------
  seiten.forEach((s, i) => {
    fussZeile(s);
    s.textRechts(rechts, RAND.unten - 12, `Seite ${i + 1} von ${seiten.length}`,
                 7, false, GRAU);
  });

  return pdfBauen(seiten);
}

// ===========================================================================
// Durchlauf
// ===========================================================================

// Der Schreibknoten dahinter legt keine Ordner an.
const ZIELORDNER = '/data/ausgabe/rechnungen';
try {
  require('fs').mkdirSync(ZIELORDNER, { recursive: true });
} catch (e) {
  // Scheitert es hier, meldet sich der Schreibknoten mit einer klaren Meldung.
}

const ausgabe = [];
for (const eintrag of $input.all()) {
  const r = eintrag.json;
  verstuemmelt.clear();

  const bytes = rechnungBauen(r);
  const dateiname = `Rechnung_${String(r.rechnungsnummer).replace(/[^\w.-]/g, '_')}.pdf`;

  ausgabe.push({
    json: {
      rechnungsnummer: r.rechnungsnummer,
      kunde: r.kunde,
      datei: r.datei,
      pdf: dateiname,
      posten: r.posten.length,
      brutto: r.brutto,
      groesse: bytes.length,
      ersetzteZeichen: [...verstuemmelt],
    },
    binary: {
      data: await this.helpers.prepareBinaryData(bytes, dateiname, 'application/pdf'),
    },
  });
}

return ausgabe;

// ---------------------------------------------------------------------------
// Alle Beanstandungen in eine CSV, die man in Excel oeffnen kann.
// Modus: "Run Once for All Items".
//
// Der Dateiname bekommt einen Zeitstempel. Ohne ihn bliebe der Bericht des
// letzten Laufs liegen und saehe beim naechsten Blick aus wie der aktuelle -
// derselbe Fallstrick wie beim Vorgaengerworkflow.
// ---------------------------------------------------------------------------

function stempel() {
  // 'sv-SE' liefert 2026-09-18 21:04:11, also fast ISO. Die Zeitzone muss
  // ausdruecklich mit: der Task-Runner von n8n laeuft in UTC, auch wenn der
  // Container auf Europe/Berlin steht.
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
  return s.slice(0, 10) + '_' + s.slice(11, 16).replace(':', '-');
}

const SPALTEN = ['datei', 'zeile', 'rechnungsnummer', 'problem'];

function feld(wert) {
  const s = String(wert ?? '');
  return /[";\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

const faelle = $input.all().map(e => e.json);

const zeilen = [SPALTEN.join(';')];
for (const f of faelle) zeilen.push(SPALTEN.map(s => feld(f[s])).join(';'));

// Byte Order Mark voran, sonst zeigt Excel die Umlaute als Kraut an.
const text = '﻿' + zeilen.join('\r\n') + '\r\n';
const zielname = `problemfaelle_${stempel()}.csv`;

const binaer = await this.helpers.prepareBinaryData(
  Buffer.from(text, 'utf8'), zielname, 'text/csv');

return [{
  json: {
    zielname,
    anzahl: faelle.length,
    // Welche Quelldateien betroffen sind, entscheidet nachher darueber,
    // ob die Datei weggeraeumt oder zum Nachsehen hingelegt wird.
    betroffeneDateien: [...new Set(faelle.map(f => f.datei))],
  },
  binary: { data: binaer },
}];

// ---------------------------------------------------------------------------
// Die abgearbeiteten CSV-Dateien aus dem Eingang nehmen.
// Modus: "Run Once for All Items".
//
// Erst hier, nachdem alle Ausgaben geschrieben sind. Bricht vorher etwas ab,
// bleiben die Dateien liegen und der naechste Lauf holt sie erneut.
//
// Sauber gelaufene Dateien wandern nach _beiseite, beanstandete nach pruefen -
// so sieht man am Ordner, wo noch jemand hinschauen muss.
//
// Den Knoten "Execute Command" gibt es im offiziellen Image nicht mehr,
// verschoben wird deshalb mit fs. Dafuer braucht der Container
// NODE_FUNCTION_ALLOW_BUILTIN=fs.
// ---------------------------------------------------------------------------

const fs = require('fs');

const EINGANG = '/data/csv';
const ERLEDIGT = '/data/_beiseite';
const NACHSEHEN = '/data/pruefen';

function stempel() {
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
  return s.slice(0, 10) + '_' + s.slice(11, 16).replace(':', '-');
}

function eintraege(knoten) {
  try {
    return $(knoten).all();
  } catch (e) {
    return [];   // Zweig ist in diesem Lauf nicht angelaufen
  }
}

const quelldateien = eintraege('CSV-Dateien lesen')
  .map(e => e.binary?.data?.fileName)
  .filter(Boolean);

const beanstandet = new Set(
  eintraege('Rechnungen pruefen')
    .filter(e => e.json.ok === false)
    .map(e => e.json.datei));

const jetzt = stempel();
const verschoben = [];

for (const ordner of [ERLEDIGT, NACHSEHEN]) {
  fs.mkdirSync(ordner, { recursive: true });
}

for (const name of quelldateien) {
  const ziel = beanstandet.has(name) ? NACHSEHEN : ERLEDIGT;
  const von = `${EINGANG}/${name}`;
  const nach = `${ziel}/${jetzt}_${name}`;
  try {
    fs.renameSync(von, nach);
    verschoben.push({ datei: name, nach: ziel, beanstandet: beanstandet.has(name) });
  } catch (e) {
    verschoben.push({ datei: name, nach: null, fehler: e.message });
  }
}

return [{ json: { zeitpunkt: jetzt, verschoben } }];

// ---------------------------------------------------------------------------
// Eine Zeile je Lauf, angehaengt an /data/ausgabe/protokoll.txt.
// Modus: "Run Once for All Items".
//
// Die Zahlen kommen von den Quellknoten, nicht aus dem Eingang - so stimmt die
// Zaehlung auch, wenn ein Zweig gar nicht gelaufen ist.
// ---------------------------------------------------------------------------

function stempel() {
  return new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' });
}

function eintraege(knoten) {
  try {
    return $(knoten).all().filter(e => e.json && Object.keys(e.json).length > 0);
  } catch (e) {
    return [];
  }
}

const zeitpunkt = stempel();
const gelesen = eintraege('CSV-Zeilen lesen');
const rechnungen = eintraege('Rechnungen pruefen').filter(e => e.json.ok === true);
const probleme = eintraege('Rechnungen pruefen').filter(e => e.json.ok === false);
const pdfs = eintraege('Rechnung als PDF');
const aufraeumen = eintraege('Verarbeitete wegraeumen');

const dateien = [...new Set(gelesen.map(e => e.json.__datei))];
const brutto = rechnungen.reduce((a, e) => a + (e.json.brutto ?? 0), 0);

let zeile = `${zeitpunkt} | ${dateien.length} Datei(en) | ${gelesen.length} Zeilen`
          + ` | ${pdfs.length} PDF | ${probleme.length} beanstandet`
          + ` | brutto ${brutto.toFixed(2)}`;

// Ersetzte Sonderzeichen kommen ins Protokoll, damit niemand ein still
// verstuemmeltes PDF verschickt, ohne davon zu wissen.
const ersetzt = [...new Set(pdfs.flatMap(e => e.json.ersetzteZeichen || []))];
if (ersetzt.length) {
  zeile += `\n    ~ Zeichen ersetzt: ${ersetzt.join(' ')}`;
}

for (const e of probleme) {
  const wo = e.json.zeile ? `Zeile ${e.json.zeile}` : e.json.rechnungsnummer;
  zeile += `\n    ! ${e.json.datei} ${wo}: ${e.json.problem}`;
}

for (const v of aufraeumen[0]?.json?.verschoben || []) {
  if (v.fehler) zeile += `\n    ! ${v.datei} blieb liegen: ${v.fehler}`;
}

const text = zeile + '\n';
const binaer = await this.helpers.prepareBinaryData(
  Buffer.from(text, 'utf8'), 'protokoll.txt', 'text/plain');

return [{
  json: {
    zeitpunkt,
    dateien: dateien.length,
    zeilen: gelesen.length,
    pdf: pdfs.length,
    beanstandet: probleme.length,
  },
  binary: { data: binaer },
}];
